def _datos():
    """Decisiones de las observaciones al demo v0.7 sobre una base existente (la sincronización de catálogos solo agrega
    lo nuevo y no modifica lo configurado)."""
    import json
    bind = op.get_bind()
    O7 = "Observaciones al demo v0.7 (15-oct-2026)"
    # el precertificado se emite después del picking
    bind.execute(sa.text("UPDATE params SET valor = :v, estado = 'DEFINIDO', fuente = :f WHERE key = 'certificado_previo_al_picking'"),
                 {"v": json.dumps({"v": False}), "f": f"{O7}: el precertificado solo se emite después del picking"})
    # destinatarios de la alerta de picking y de la presolicitud de compra
    for code, roles in (("PICKING_PROGRAMADO", ["LIDER_ALMACEN", "COORD_ALMACEN", "COORD_ALMACEN_MP", "JEFE_LOGISTICA",
                                                "COORD_LOGISTICA", "GERENCIA_OPERACIONES"]),
                        ("COMPRA_APROBACION_LOGISTICA", ["JEFE_LOGISTICA", "COORD_LOGISTICA", "COORD_ALMACEN", "COORD_ALMACEN_MP"])):
        bind.execute(sa.text("UPDATE alert_types SET roles = :r WHERE code = :c"), {"r": json.dumps(roles), "c": code})
    # capacidad por línea según la tabla de capacidades (14 y 15-oct-2026)
    for code, nombre, cap in (("CIMBRIA", "IQ+CIMB (selección Cimbria)", 25500), ("TRUER", "TRUER (selección)", 12750),
                              ("SEL_MANUAL", "SEL. MANUAL (selección manual)", 4250), ("R1", "RAUMAK 1 (envasado automático R1)", None),
                              ("R2", "RAUMAK 2 (envasado automático R2)", None), ("R3", "RAUMAK 3 (envasado automático R3)", 29750),
                              ("ENV_MANUAL", "ENV. MANUAL (envasado manual)", 2550)):
        bind.execute(sa.text("UPDATE production_lines SET nombre = :n, capacidad_kg_dia = COALESCE(capacidad_kg_dia, :c) "
                             "WHERE code = :k"), {"n": nombre, "c": cap, "k": code})


